/**
 * announceToScreenReader - Send a message to a live region for screen readers.
 *
 * Uses an offscreen aria-live container. Supports polite (default) and assertive.
 * Returns a cleanup function to remove the announcement.
 *
 * @remarks
 * The utility creates a shared live region element keyed by `id`. When reusing an
 * existing container, it updates the `role`, `aria-live`, and `aria-atomic` attributes
 * to match the current call's options, ensuring assertive announcements remain assertive.
 *
 * @example
 * ```ts
 * // Polite announcement (default)
 * const cleanup = announceToScreenReader('Item saved successfully');
 *
 * // Assertive announcement using the boolean alias
 * const cleanup = announceToScreenReader('Critical error occurred', { assertive: true });
 *
 * // Assertive announcement using politeness option
 * const cleanup = announceToScreenReader('Critical error occurred', { politeness: 'assertive' });
 * ```
 *
 * @param message - The message to announce to screen readers
 * @param options - Configuration options for the announcement
 * @returns A cleanup function that clears the announcement and cancels any pending timeout
 */
export interface AnnounceOptions {
  /**
   * The politeness level of the announcement.
   * - 'polite': Waits for a pause in screen reader speech (default)
   * - 'assertive': Interrupts current speech immediately
   */
  readonly politeness?: 'polite' | 'assertive';
  /**
   * Convenience alias for `politeness: 'assertive'`.
   * When true, sets politeness to 'assertive'. If both `assertive` and `politeness`
   * are provided, `politeness` takes precedence.
   */
  readonly assertive?: boolean;
  /**
   * Unique ID for the live region element. Defaults to 'dsai-live-region'.
   * Use different IDs to create separate live regions for different announcement types.
   */
  readonly id?: string;
  /**
   * Duration in milliseconds before the announcement text is cleared.
   * Defaults to 2000ms.
   */
  readonly timeoutMs?: number;
}

export function announceToScreenReader(message: string, options: AnnounceOptions = {}): () => void {
  // SSR safety: early return if no document
  if (typeof document === 'undefined') {
    return () => {};
  }

  const {
    politeness: explicitPoliteness,
    assertive = false,
    id = 'dsai-live-region',
    timeoutMs = 2000,
  } = options;

  // Resolve politeness: explicit politeness takes precedence, then assertive boolean, then default
  const politeness: 'polite' | 'assertive' =
    explicitPoliteness ?? (assertive ? 'assertive' : 'polite');

  // Determine the appropriate role based on politeness
  const role = politeness === 'assertive' ? 'alert' : 'status';

  // Guard against document.body not being available (e.g., called before DOM is ready)
  const parentElement = document.body ?? document.documentElement;

  let container = document.getElementById(id);
  if (!container) {
    container = document.createElement('div');
    container.id = id;
    // Apply visually hidden styles
    container.style.position = 'absolute';
    container.style.width = '1px';
    container.style.height = '1px';
    container.style.margin = '-1px';
    container.style.border = '0';
    container.style.padding = '0';
    container.style.overflow = 'hidden';
    container.style.clip = 'rect(0 0 0 0)';
    parentElement.appendChild(container);
  }

  // Always update ARIA attributes to ensure correct behavior on reuse
  container.setAttribute('role', role);
  container.setAttribute('aria-live', politeness);
  container.setAttribute('aria-atomic', 'true');

  container.textContent = message;

  const timeoutId = window.setTimeout(() => {
    if (container?.parentNode) {
      container.textContent = '';
    }
  }, timeoutMs);

  // Return cleanup function
  return () => {
    if (timeoutId) {
      window.clearTimeout(timeoutId);
    }
    if (container?.parentNode) {
      container.textContent = '';
    }
  };
}

export default announceToScreenReader;

/**
 * @file buildAriaLabel - Build comprehensive ARIA label attributes
 * @module @dsai-io/react/utils/a11y
 *
 * Enterprise-grade ARIA label builder with:
 * - Combines label, labelledby, and describedby
 * - Handles multiple ID references
 * - Validates and sanitizes IDs
 * - Returns proper ARIA attributes object
 */

import type { BuildAriaLabelOptions } from '../types/shared';

/**
 * Build ARIA label attributes from various sources
 *
 * @param options - Label building options
 * @returns Object with aria-label, aria-labelledby, aria-describedby
 *
 * @example
 * ```tsx
 * // Basic label
 * buildAriaLabel({ label: 'Submit form' });
 * // => { 'aria-label': 'Submit form' }
 *
 * // Label by reference
 * buildAriaLabel({ labelledBy: 'form-title' });
 * // => { 'aria-labelledby': 'form-title' }
 *
 * // Multiple labelledby IDs
 * buildAriaLabel({ labelledBy: ['title', 'subtitle'] });
 * // => { 'aria-labelledby': 'title subtitle' }
 *
 * // With description
 * buildAriaLabel({
 *   label: 'Email',
 *   description: 'Enter your email address'
 * });
 * // => { 'aria-label': 'Email', 'aria-describedby': undefined }
 *
 * // Complex example
 * buildAriaLabel({
 *   labelledBy: 'dialog-title',
 *   describedBy: ['dialog-desc', 'dialog-help'],
 *   description: 'Additional context'
 * });
 * // => {
 * //   'aria-labelledby': 'dialog-title',
 * //   'aria-describedby': 'dialog-desc dialog-help'
 * // }
 * ```
 */
export function buildAriaLabel(options: BuildAriaLabelOptions): {
  'aria-label'?: string;
  'aria-labelledby'?: string;
  'aria-describedby'?: string;
} {
  const { label, labelledBy, describedBy } = options;

  const result: {
    'aria-label'?: string;
    'aria-labelledby'?: string;
    'aria-describedby'?: string;
  } = {};

  // Priority: labelledBy > label
  if (labelledBy) {
    const ids = Array.isArray(labelledBy) ? labelledBy : [labelledBy];
    const sanitizedIds = ids
      .filter((id) => typeof id === 'string' && id.trim().length > 0)
      .map((id) => id.trim());

    if (sanitizedIds.length > 0) {
      result['aria-labelledby'] = sanitizedIds.join(' ');
    }
  } else if (label && label.trim().length > 0) {
    result['aria-label'] = label.trim();
  }

  // Handle describedBy
  if (describedBy) {
    const ids = Array.isArray(describedBy) ? describedBy : [describedBy];
    const sanitizedIds = ids
      .filter((id) => typeof id === 'string' && id.trim().length > 0)
      .map((id) => id.trim());

    if (sanitizedIds.length > 0) {
      result['aria-describedby'] = sanitizedIds.join(' ');
    }
  }

  // Note: description text is not used directly in ARIA attributes
  // It should be rendered as visible text with an ID, then referenced via describedBy

  return result;
}

/**
 * @file combineAriaDescriptions - Merge multiple aria-describedby IDs
 * @module @dsai-io/react/utils/a11y
 *
 * Enterprise-grade aria-describedby combiner with:
 * - Merges multiple ID references
 * - Removes duplicates
 * - Validates and sanitizes IDs
 * - Preserves order
 */

/**
 * Combine multiple aria-describedby ID references into a single space-separated string
 *
 * @param ids - Array of ID strings or single ID
 * @returns Space-separated string of unique IDs
 *
 * @example
 * ```tsx
 * // Single ID
 * combineAriaDescriptions('help-text');
 * // => 'help-text'
 *
 * // Multiple IDs
 * combineAriaDescriptions(['help-text', 'error-message']);
 * // => 'help-text error-message'
 *
 * // Remove duplicates
 * combineAriaDescriptions(['help-text', 'help-text', 'error']);
 * // => 'help-text error'
 *
 * // Filter empty strings
 * combineAriaDescriptions(['help-text', '', null, 'error']);
 * // => 'help-text error'
 *
 * // Mixed input
 * combineAriaDescriptions(['id1', 'id2', undefined, 'id3', 'id1']);
 * // => 'id1 id2 id3'
 * ```
 */
export function combineAriaDescriptions(
  ...ids: Array<string | readonly string[] | null | undefined>
): string {
  // Flatten all inputs
  const allIds: string[] = [];

  for (const id of ids) {
    if (id === null || id === undefined) {
      continue;
    }

    if (Array.isArray(id)) {
      allIds.push(...id);
    } else if (typeof id === 'string') {
      allIds.push(id);
    }
  }

  // Filter, trim, and deduplicate
  const seen = new Set<string>();
  const uniqueIds: string[] = [];

  for (const id of allIds) {
    if (typeof id !== 'string') {
      continue;
    }

    const trimmed = id.trim();
    if (trimmed.length > 0 && !seen.has(trimmed)) {
      seen.add(trimmed);
      uniqueIds.push(trimmed);
    }
  }

  return uniqueIds.join(' ');
}

/**
 * @file createRovingTabindex - Roving tabindex manager
 * @module @dsai-io/react/utils/a11y
 *
 * Enterprise-grade roving tabindex with:
 * - Manages tabindex across focusable items
 * - Keyboard navigation (arrows, home, end)
 * - Looping/wrapping support
 * - Orientation-aware (horizontal/vertical/both)
 * - Clean cleanup
 */

import type { RovingTabindexManager, RovingTabindexOptions } from '../types/shared';

/**
 * Create a roving tabindex manager for keyboard navigation
 *
 * @param container - Container element with focusable children
 * @param options - Roving tabindex options
 * @returns Manager with focus control methods
 *
 * @throws {TypeError} If container is not an Element
 *
 * @example
 * ```tsx
 * // Basic horizontal toolbar
 * const toolbar = document.getElementById('toolbar');
 * const manager = createRovingTabindex(toolbar, {
 *   itemSelector: 'button',
 *   orientation: 'horizontal'
 * });
 *
 * // Focus first item
 * manager.focusFirst();
 *
 * // Cleanup when done
 * manager.destroy();
 *
 * // Vertical list with looping
 * const list = document.getElementById('menu');
 * const menuManager = createRovingTabindex(list, {
 *   itemSelector: '[role="menuitem"]',
 *   orientation: 'vertical',
 *   loop: true
 * });
 *
 * // React usage
 * useEffect(() => {
 *   const manager = createRovingTabindex(ref.current, {
 *     itemSelector: '.tab',
 *     orientation: 'horizontal'
 *   });
 *
 *   return () => manager.destroy();
 * }, []);
 * ```
 */
export function createRovingTabindex(
  target: Element | Element[],
  options: RovingTabindexOptions = { itemSelector: '[data-roving-item]' }
): RovingTabindexManager {
  const isElementArray = Array.isArray(target);
  const container = isElementArray ? (target[0]?.parentElement ?? document.body) : target;

  // Validate container
  if (!(container instanceof Element)) {
    throw new TypeError('createRovingTabindex expects an Element as container');
  }

  const { itemSelector, enableKeyboard = true, loop = true, orientation = 'horizontal' } = options;

  let currentIndex = 0;
  let items: Element[] = [];

  /**
   * Get all focusable items
   */
  function getItems(): Element[] {
    if (isElementArray) {
      return [...(target as Element[])];
    }

    if (!itemSelector) {
      throw new TypeError('createRovingTabindex requires itemSelector when container is used');
    }

    return Array.from(container.querySelectorAll(itemSelector));
  }

  /**
   * Update items and tabindex attributes
   */
  function updateItems(): void {
    items = getItems();

    items.forEach((item, index) => {
      if (index === currentIndex) {
        item.setAttribute('tabindex', '0');
      } else {
        item.setAttribute('tabindex', '-1');
      }
    });
  }

  /**
   * Focus item at index
   */
  function focusAt(index: number): void {
    if (index < 0 || index >= items.length) {
      return;
    }

    currentIndex = index;
    updateItems();

    // Safe: index is validated above
    const item = items[index];
    if (item instanceof HTMLElement) {
      item.focus();
    }
  }

  /**
   * Focus first item
   */
  function focusFirst(): void {
    focusAt(0);
  }

  /**
   * Focus last item
   */
  function focusLast(): void {
    focusAt(items.length - 1);
  }

  /**
   * Focus next item
   */
  function focusNext(): void {
    let nextIndex = currentIndex + 1;

    if (nextIndex >= items.length) {
      nextIndex = loop ? 0 : items.length - 1;
    }

    focusAt(nextIndex);
  }

  /**
   * Focus previous item
   */
  function focusPrevious(): void {
    let prevIndex = currentIndex - 1;

    if (prevIndex < 0) {
      prevIndex = loop ? items.length - 1 : 0;
    }

    focusAt(prevIndex);
  }

  /**
   * Get current focused index
   */
  function getCurrentIndex(): number {
    return currentIndex;
  }

  /**
   * Handle keyboard events
   */
  function handleKeyDown(event: KeyboardEvent): void {
    const { key } = event;

    // Handle Home/End
    if (key === 'Home') {
      event.preventDefault();
      focusFirst();
      return;
    }

    if (key === 'End') {
      event.preventDefault();
      focusLast();
      return;
    }

    // Handle arrow keys based on orientation
    const isHorizontal = orientation === 'horizontal' || orientation === 'both';
    const isVertical = orientation === 'vertical' || orientation === 'both';

    if (isHorizontal && (key === 'ArrowLeft' || key === 'ArrowRight')) {
      event.preventDefault();
      if (key === 'ArrowLeft') {
        focusPrevious();
      } else {
        focusNext();
      }
      return;
    }

    if (isVertical && (key === 'ArrowUp' || key === 'ArrowDown')) {
      event.preventDefault();
      if (key === 'ArrowUp') {
        focusPrevious();
      } else {
        focusNext();
      }
      return;
    }
  }

  // Initialize
  updateItems();

  // Add keyboard listener if enabled
  if (enableKeyboard) {
    container.addEventListener('keydown', handleKeyDown as EventListener);
  }

  // Return manager interface
  return {
    getCurrentIndex,
    focusAt,
    focusFirst,
    focusLast,
    focusNext,
    focusPrevious,
    destroy: (): void => {
      if (enableKeyboard) {
        container.removeEventListener('keydown', handleKeyDown as EventListener);
      }
      items = [];
    },
  };
}

/**
 * A curated list of selectors that are typically focusable by keyboard.
 * Source: WCAG patterns and common component libraries.
 */
export const focusableSelectors = [
  'a[href]',
  'area[href]',
  'button:not([disabled])',
  'input:not([disabled])',
  'select:not([disabled])',
  'textarea:not([disabled])',
  'summary',
  'iframe',
  '[tabindex]:not([tabindex="-1"])',
  '[contenteditable="true"]',
] as const;

/** Convenience string for querySelectorAll */
export const focusableSelectorString = focusableSelectors.join(',');

export default focusableSelectors;

// Counter for deterministic, SSR-safe ID generation
let counter = 0;

/**
 * generateId - SSR-safe, deterministic ID generator with prefix support.
 *
 * Uses an incrementing counter to ensure consistent IDs across SSR and client.
 * This is the canonical implementation used throughout the design system.
 *
 * @param prefix - Optional prefix for the ID (default: 'id')
 * @returns A unique ID string in the format `${prefix}-${counter}`
 *
 * @example
 * const id = generateId('input'); // => 'input-1'
 * const id2 = generateId('button'); // => 'button-2'
 */
export function generateId(prefix = 'id'): string {
  counter += 1;
  return `${prefix}-${counter}`;
}

export default generateId;

/**
 * @file getAnimationDuration - Get animation duration based on user preference
 * @module @dsai-io/react/utils/a11y
 *
 * Enterprise-grade animation duration calculator with:
 * - Respects prefers-reduced-motion (returns 0ms)
 * - Predefined duration scales
 * - Type-safe duration values
 * - SSR-safe
 */

import { shouldAnimate } from './shouldAnimate';

import type { AnimationDuration } from '../types/shared';

/**
 * Get animation duration in milliseconds, respecting user's motion preferences
 *
 * @param requestedDuration - Desired duration in milliseconds
 * @returns 0 if reduced motion preferred, otherwise requested duration
 *
 * @example
 * ```tsx
 * // Basic usage
 * const duration = getAnimationDuration(300);
 * // => 300 if animations enabled, 0 if reduced motion
 *
 * // With CSS
 * element.style.transitionDuration = `${getAnimationDuration(200)}ms`;
 *
 * // With React Spring
 * const springs = useSpring({
 *   opacity: visible ? 1 : 0,
 *   config: { duration: getAnimationDuration(300) }
 * });
 *
 * // With Framer Motion
 * <motion.div
 *   initial={{ opacity: 0 }}
 *   animate={{ opacity: 1 }}
 *   transition={{ duration: getAnimationDuration(500) / 1000 }}
 * />
 *
 * // Predefined durations
 * getAnimationDuration(150); // Fast
 * getAnimationDuration(300); // Normal
 * getAnimationDuration(500); // Slow
 * ```
 */
export function getAnimationDuration(requestedDuration: AnimationDuration): number {
  return shouldAnimate() ? requestedDuration : 0;
}

/**
 * Predefined animation durations (in milliseconds)
 */
export const ANIMATION_DURATION = {
  /**
   * Instant (no animation)
   */
  INSTANT: 0 as const,

  /**
   * Fast animations (150ms)
   */
  FAST: 150 as const,

  /**
   * Normal animations (200ms)
   */
  NORMAL: 200 as const,

  /**
   * Standard animations (300ms)
   */
  STANDARD: 300 as const,

  /**
   * Slow animations (500ms)
   */
  SLOW: 500 as const,
} as const;

/**
 * Get fast animation duration (150ms or 0ms)
 */
export function getFastDuration(): number {
  return getAnimationDuration(ANIMATION_DURATION.FAST);
}

/**
 * Get normal animation duration (200ms or 0ms)
 */
export function getNormalDuration(): number {
  return getAnimationDuration(ANIMATION_DURATION.NORMAL);
}

/**
 * Get standard animation duration (300ms or 0ms)
 */
export function getStandardDuration(): number {
  return getAnimationDuration(ANIMATION_DURATION.STANDARD);
}

/**
 * Get slow animation duration (500ms or 0ms)
 */
export function getSlowDuration(): number {
  return getAnimationDuration(ANIMATION_DURATION.SLOW);
}

/**
 * @file getArrowKeyHandler - Arrow key navigation handler
 * @module @dsai-io/react/utils/a11y
 *
 * Enterprise-grade arrow key handler with:
 * - Maps arrow keys to actions
 * - Prevents default behavior
 * - Type-safe handler map
 * - Supports all arrow directions
 */

import type { ArrowKey, ArrowKeyHandlers } from '../types/shared';

/**
 * Static allowlist of valid arrow keys to prevent dynamic property access attacks.
 * This is a compile-time constant that ensures only these specific keys can be used.
 */
const ARROW_KEYS: ReadonlySet<ArrowKey> = new Set([
  'ArrowUp',
  'ArrowDown',
  'ArrowLeft',
  'ArrowRight',
] as const);

/**
 * Type guard to check if a string is a valid arrow key
 */
function isArrowKey(key: string): key is ArrowKey {
  return ARROW_KEYS.has(key as ArrowKey);
}

/**
 * Create a keyboard event handler for arrow key navigation
 *
 * @param handlers - Map of arrow keys to handler functions
 * @returns Keyboard event handler function
 *
 * @example
 * ```tsx
 * // Basic usage
 * const handleKeyDown = getArrowKeyHandler({
 *   ArrowUp: (e) => {
 *     e.preventDefault();
 *     focusPreviousItem();
 *   },
 *   ArrowDown: (e) => {
 *     e.preventDefault();
 *     focusNextItem();
 *   }
 * });
 *
 * element.addEventListener('keydown', handleKeyDown);
 *
 * // Horizontal navigation
 * const handleHorizontal = getArrowKeyHandler({
 *   ArrowLeft: (e) => {
 *     e.preventDefault();
 *     selectPrevious();
 *   },
 *   ArrowRight: (e) => {
 *     e.preventDefault();
 *     selectNext();
 *   }
 * });
 *
 * // All directions
 * const handleGrid = getArrowKeyHandler({
 *   ArrowUp: (e) => navigateUp(e),
 *   ArrowDown: (e) => navigateDown(e),
 *   ArrowLeft: (e) => navigateLeft(e),
 *   ArrowRight: (e) => navigateRight(e)
 * });
 *
 * // With React
 * <div onKeyDown={getArrowKeyHandler({
 *   ArrowUp: () => setIndex(i => Math.max(0, i - 1)),
 *   ArrowDown: () => setIndex(i => Math.min(max, i + 1))
 * })} />
 * ```
 */
export function getArrowKeyHandler(handlers: ArrowKeyHandlers): (event: KeyboardEvent) => void {
  return (event: KeyboardEvent): void => {
    const key = event.key;

    // Security: validate key against static allowlist before property access
    if (!isArrowKey(key)) {
      return;
    }

    // Safe: key is now validated as one of the four arrow key literals
    // Use explicit switch statement instead of dynamic property access
    switch (key) {
      case 'ArrowUp':
        handlers.ArrowUp?.(event);
        break;
      case 'ArrowDown':
        handlers.ArrowDown?.(event);
        break;
      case 'ArrowLeft':
        handlers.ArrowLeft?.(event);
        break;
      case 'ArrowRight':
        handlers.ArrowRight?.(event);
        break;
    }
  };
}

export { announceToScreenReader, type AnnounceOptions } from './announceToScreenReader';
export { buildAriaLabel } from './buildAriaLabel';
export { combineAriaDescriptions } from './combineAriaDescriptions';
export { createRovingTabindex } from './createRovingTabindex';
export { focusableSelectorString, focusableSelectors } from './focusableSelectors';
export { generateId } from './generateId';
export {
  ANIMATION_DURATION,
  getAnimationDuration,
  getFastDuration,
  getNormalDuration,
  getSlowDuration,
  getStandardDuration,
} from './getAnimationDuration';
export { getArrowKeyHandler } from './getArrowKeyHandler';
export { onAnimationPreferenceChange, shouldAnimate } from './shouldAnimate';
export { trapFocus, type TrapFocusOptions } from './trapFocus';

/**
 * @file shouldAnimate - Check if animations should run
 * @module @dsai-io/react/utils/a11y
 *
 * Enterprise-grade animation preference checker with:
 * - Respects prefers-reduced-motion
 * - SSR-safe
 * - Browser fallback
 * - Caches media query
 */

let cachedMediaQuery: MediaQueryList | null = null;

/**
 * Check if animations should be enabled based on user preferences
 *
 * @returns true if animations should run, false if reduced motion preferred
 *
 * @example
 * ```tsx
 * // Basic usage
 * if (shouldAnimate()) {
 *   element.classList.add('animate-fade-in');
 * }
 *
 * // React usage
 * const [animate, setAnimate] = useState(shouldAnimate());
 *
 * useEffect(() => {
 *   if (!shouldAnimate()) {
 *     setAnimate(false);
 *   }
 * }, []);
 *
 * // Conditional animation
 * <div className={shouldAnimate() ? 'transition-all' : ''}>
 *   Content
 * </div>
 *
 * // With CSS-in-JS
 * const styles = {
 *   transition: shouldAnimate() ? 'all 0.3s ease' : 'none'
 * };
 * ```
 */
export function shouldAnimate(): boolean {
  // SSR fallback - default to no animations
  if (typeof window === 'undefined' || !window.matchMedia) {
    return false;
  }

  // Cache media query for performance
  if (!cachedMediaQuery) {
    cachedMediaQuery = window.matchMedia('(prefers-reduced-motion: reduce)');
  }

  // Return true if reduced motion is NOT preferred
  return !cachedMediaQuery.matches;
}

/**
 * Listen for changes to animation preferences
 *
 * @param callback - Function called when preference changes
 * @returns Cleanup function
 *
 * @example
 * ```tsx
 * // React usage
 * useEffect(() => {
 *   return onAnimationPreferenceChange((shouldAnimate) => {
 *     setAnimationsEnabled(shouldAnimate);
 *   });
 * }, []);
 * ```
 */
export function onAnimationPreferenceChange(
  callback: (shouldAnimate: boolean) => void
): () => void {
  // SSR fallback
  if (typeof window === 'undefined' || !window.matchMedia) {
    return () => {};
  }

  if (!cachedMediaQuery) {
    cachedMediaQuery = window.matchMedia('(prefers-reduced-motion: reduce)');
  }

  const handler = (event: MediaQueryListEvent): void => {
    callback(!event.matches);
  };

  cachedMediaQuery.addEventListener('change', handler);

  return (): void => {
    if (cachedMediaQuery) {
      cachedMediaQuery.removeEventListener('change', handler);
    }
  };
}

/**
 * trapFocus - Creates a focus trap within a container element.
 *
 * Returns a cleanup function to remove listeners.
 * NOTE: Should be used sparingly; ensure escape/close affordance is present.
 */
export interface TrapFocusOptions {
  /**
   * CSS selectors to identify focusable elements inside the container.
   */
  readonly focusableSelectors?: readonly string[];
  /**
   * Optional handler when focus wraps (e.g., for analytics).
   */
  readonly onWrap?: () => void;
  /**
   * Optional handler when Escape key is pressed to close the trap.
   */
  readonly onEscape?: () => void;
  /**
   * Whether to focus the first focusable element on mount.
   * @default false
   */
  readonly initialFocus?: boolean;
}

const DEFAULT_SELECTORS = [
  'a[href]',
  'button:not([disabled])',
  'textarea:not([disabled])',
  'input:not([disabled])',
  'select:not([disabled])',
  '[tabindex]:not([tabindex="-1"])',
];

/**
 * Check if an element is visible (handles JSDOM where offsetParent is always null)
 * @internal
 */
function isElementVisible(el: HTMLElement): boolean {
  // SSR safety: if we somehow get here without a window, assume visible
  if (typeof window === 'undefined') {
    return true;
  }
  const style = getComputedStyle(el);
  if (style.visibility === 'hidden' || style.display === 'none') {
    return false;
  }
  if (!el.isConnected) {
    return false;
  }
  // In JSDOM, offsetParent is always null, so we only use it as a positive signal
  return true;
}

export function trapFocus(container: HTMLElement, options: TrapFocusOptions = {}): () => void {
  // SSR safety: bail early if no window/document
  if (typeof window === 'undefined' || typeof document === 'undefined') {
    return () => {};
  }

  // Input validation: ensure container is a valid element
  if (!container || !(container instanceof HTMLElement)) {
    if (process.env['NODE_ENV'] !== 'production') {
      console.warn('[trapFocus] Invalid container element provided');
    }
    return () => {};
  }

  const selectors = options.focusableSelectors ?? DEFAULT_SELECTORS;
  const focusable = Array.from(container.querySelectorAll<HTMLElement>(selectors.join(','))).filter(
    isElementVisible
  );

  if (focusable.length === 0) {
    if (process.env['NODE_ENV'] !== 'production') {
      console.warn('[trapFocus] No focusable elements found in container');
    }
    return () => {};
  }

  // Safe to access since we checked length > 0
  const firstEl = focusable[0] as HTMLElement;
  const lastEl = focusable[focusable.length - 1] as HTMLElement;
  if (!firstEl || !lastEl) {
    return () => {};
  }

  // Initial focus if requested
  if (options.initialFocus) {
    firstEl.focus();
  }

  function handleKeyDown(event: KeyboardEvent): void {
    // Escape key handling
    if (event.key === 'Escape' && options.onEscape) {
      event.preventDefault();
      options.onEscape();
      return;
    }

    if (event.key !== 'Tab') {
      return;
    }
    if (focusable.length === 1) {
      event.preventDefault();
      firstEl.focus();
      options.onWrap?.();
      return;
    }

    if (event.shiftKey && document.activeElement === firstEl) {
      event.preventDefault();
      lastEl.focus();
      options.onWrap?.();
    } else if (!event.shiftKey && document.activeElement === lastEl) {
      event.preventDefault();
      firstEl.focus();
      options.onWrap?.();
    }
  }

  container.addEventListener('keydown', handleKeyDown);

  return () => {
    container.removeEventListener('keydown', handleKeyDown);
  };
}

export default trapFocus;
